import { DataTexture } from 'three'
import { InstancedAsteroidMaterial } from '@/core/materials/InstancedAsteroidMaterial'

function lookup(material: InstancedAsteroidMaterial): DataTexture {
  const texture = material.uniforms.uAsteroidGradients?.value
  expect(texture).toBeInstanceOf(DataTexture)
  return texture as DataTexture
}

describe('asteroid gradient resource ownership', () => {
  it.each([false, true])('owns and releases its gradient source, including repeated disposal (ice=%s)', ice => {
    const material = new InstancedAsteroidMaterial(undefined, undefined, ice)
    try {
      const texture = lookup(material)
      let releases = 0
      texture.addEventListener('dispose', () => releases++)
      material.dispose()
      expect(releases).toBe(1)
      // Three permits GPU reupload after dispose; retain the source and ownership.
      expect(lookup(material)).toBe(texture)
      expect(texture.image.data?.byteLength).toBeGreaterThan(0)
      material.dispose()
      expect(releases).toBe(2)
    } finally { material.dispose() }
  })

  it('clones with an independently releasable texture', () => {
    const source = new InstancedAsteroidMaterial(), clone = source.clone()
    try {
      const original = lookup(source), copied = lookup(clone)
      expect(copied).not.toBe(original)
      expect(copied.image.data).toEqual(original.image.data)
      let sourceReleases = 0, cloneReleases = 0
      original.addEventListener('dispose', () => sourceReleases++)
      copied.addEventListener('dispose', () => cloneReleases++)
      source.dispose()
      expect([sourceReleases, cloneReleases]).toEqual([1, 0])
      clone.dispose()
      expect([sourceReleases, cloneReleases]).toEqual([1, 1])
    } finally { source.dispose(); clone.dispose() }
  })

  it('releases the replaced lookup on copy and leaves self-copy alone', () => {
    const source = new InstancedAsteroidMaterial(), target = new InstancedAsteroidMaterial()
    try {
      const previous = lookup(target)
      let releases = 0
      previous.addEventListener('dispose', () => releases++)
      target.copy(source)
      expect(releases).toBe(1)
      const adopted = lookup(target)
      expect(adopted).not.toBe(previous)
      expect(adopted).not.toBe(lookup(source))
      let adoptedReleases = 0
      adopted.addEventListener('dispose', () => adoptedReleases++)
      target.copy(target)
      expect(lookup(target)).toBe(adopted)
      expect(adoptedReleases).toBe(0)
      target.dispose()
      expect(adoptedReleases).toBe(1)
    } finally { source.dispose(); target.dispose() }
  })
})

sources.tests/asteroidSurface/noiseLookup.gpu.ts:
import {
  BasicDepthPacking, DataTexture, DepthTexture, Float32BufferAttribute, FloatType,
  HalfFloatType, InstancedBufferAttribute, InstancedMesh, Matrix4, Mesh, NoBlending,
  OrthographicCamera, PerspectiveCamera, PlaneGeometry, RGBAFormat, SphereGeometry,
  UnsignedIntType, WebGLRenderer, WebGLRenderTarget
} from 'three'
import { DepthCopyPass } from 'postprocessing'
import { InstancedAsteroidMaterial } from '@/core/materials/InstancedAsteroidMaterial'
import { noiseFunctions } from '@/core/materials/shaders/lib/chunks/Noise'

function ownedLookup(material: InstancedAsteroidMaterial): DataTexture {
  const texture = material.uniforms.uAsteroidGradients?.value as DataTexture | undefined
  if (!texture?.isDataTexture) throw new Error('Asteroid material must own its gradient lookup')
  return texture
}

function activeLookup(renderer: WebGLRenderer): void {
  const gl = renderer.getContext(), program = gl.getParameter(gl.CURRENT_PROGRAM) as WebGLProgram | null
  if (!program || !gl.getProgramParameter(program, gl.LINK_STATUS) || gl.getUniformLocation(program, 'uAsteroidGradients') === null) {
    throw new Error('Asteroid gradient lookup is not active in the linked GPU program')
  }
}

function contextEvent(canvas: HTMLCanvasElement, name: string, trigger: () => void): Promise<void> {
  return new Promise((resolve, reject) => {
    const cleanup = (): void => { clearTimeout(timer); canvas.removeEventListener(name, listener) }
    const listener = (): void => { cleanup(); resolve() }
    const timer = setTimeout(() => { cleanup(); reject(new Error('Timed out: ' + name)) }, 10000)
    canvas.addEventListener(name, listener, { once: true })
    try { trigger() } catch (error) { cleanup(); reject(error) }
  })
}

/** Compare the actual installed scalar GLSL with the independent procedural
 * reference, including negative cells, periodic seams and octave combinations. */
export async function checkAsteroidNoiseLookup() {
  const material = new InstancedAsteroidMaterial()
  const gradient = ownedLookup(material), width = 256, height = 64
  const coordinates = new Float32Array(width * height * 4)
  const boundaries = [-578, -290, -289, -288, -1, 0, 1, 288, 289, 290, 577, 578]
  let seed = 81234567
  const random = (): number => { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return seed / 4294967296 }
  for (let point = 0; point < width * height; point++) {
    if (point < boundaries.length ** 3 * 3) {
      const cell = Math.floor(point / 3), epsilon = [-0.00003, 0, 0.00003][point % 3]
      const x = boundaries[cell % 12], y = boundaries[Math.floor(cell / 12) % 12], z = boundaries[Math.floor(cell / 144) % 12]
      const unskew = (x + y + z) / 6
      coordinates.set([x - unskew + epsilon, y - unskew, z - unskew - epsilon, 1], point * 4)
    } else {
      const scale = point % 2 ? 100 : 10000
      coordinates.set([(random() * 2 - 1) * scale, (random() * 2 - 1) * scale, (random() * 2 - 1) * scale, 1], point * 4)
    }
  }
  const input = new DataTexture(coordinates, width, height, RGBAFormat, FloatType)
  input.needsUpdate = true
  const renderer = new WebGLRenderer(), gl = renderer.getContext()
  renderer.setSize(width, height)
  const target = new WebGLRenderTarget(width, height, { type: FloatType, depthBuffer: false })
  const mesh = new Mesh(new PlaneGeometry(2, 2), material), camera = new OrthographicCamera()
  mesh.frustumCulled = false
  const main = material.fragmentShader.indexOf('void main()')
  if (main < 0) throw new Error('Asteroid fragment entry missing')
  material.vertexShader = 'void main() { gl_Position = vec4(position.xy, 0.0, 1.0); }'
  material.fragmentShader = `${material.fragmentShader.slice(0, main)}
    ${noiseFunctions.replace(/\bsnoise\b/g, 'referenceNoise')}
    uniform sampler2D uCoordinates;
    void main() {
      vec3 p = texelFetch(uCoordinates, ivec2(gl_FragCoord.xy), 0).xyz;
      gl_FragColor = vec4(snoise(p), referenceNoise(p),
        0.7 * snoise(p * 1.2) + 0.3 * snoise(p * 2.6),
        0.7 * referenceNoise(p * 1.2) + 0.3 * referenceNoise(p * 2.6));
    }`
  material.uniforms.uCoordinates = { value: input }
  material.blending = NoBlending
  const sample = (candidate = material): Float32Array => {
    mesh.material = candidate
    renderer.setRenderTarget(target); renderer.render(mesh, camera); activeLookup(renderer)
    const pixels = new Float32Array(width * height * 4)
    renderer.readRenderTargetPixels(target, 0, 0, width, height, pixels)
    if (gl.getError()) throw new Error('Asteroid scalar probe WebGL error')
    return pixels
  }
  const equal = (a: Float32Array, b: Float32Array): void => {
    if (new Uint32Array(a.buffer).some((value, i) => value !== new Uint32Array(b.buffer)[i])) throw new Error('Lookup changed after lifecycle operation')
  }
  try {
    const before = sample()
    let maxSingleError = 0, maxOctaveError = 0, min = Infinity, max = -Infinity
    for (let i = 0; i < before.length; i += 4) {
      const single = Math.abs(before[i] - before[i + 1]), octave = Math.abs(before[i + 2] - before[i + 3])
      if (!Number.isFinite(single) || !Number.isFinite(octave) || single > 4e-6 || octave > 4e-6) throw new Error(`Lookup mismatch at ${i / 4}: ${single}/${octave}`)
      maxSingleError = Math.max(maxSingleError, single); maxOctaveError = Math.max(maxOctaveError, octave)
      min = Math.min(min, before[i + 1]); max = Math.max(max, before[i + 1])
    }
    if (min > -0.5 || max < 0.5) throw new Error('Reference field lacks coverage')
    const textures = renderer.info.memory.textures
    material.dispose()
    if (renderer.info.memory.textures !== textures - 1) throw new Error('Material retained uploaded lookup')
    equal(before, sample()); material.dispose()
    if (renderer.info.memory.textures !== textures - 1) throw new Error('Reused material retained uploaded lookup')
    const clone = material.clone()
    clone.uniforms.uCoordinates.value = input
    try { equal(before, sample(clone)); material.dispose(); equal(before, sample(clone)) } finally { clone.dispose() }
    equal(before, sample())
    renderer.setRenderTarget(null); target.dispose(); mesh.geometry.dispose()
    await contextEvent(renderer.domElement, 'webglcontextlost', () => renderer.forceContextLoss())
    await new Promise(resolve => setTimeout(resolve, 100))
    await contextEvent(renderer.domElement, 'webglcontextrestored', () => renderer.forceContextRestore())
    equal(before, sample())
    const restoredTextures = renderer.info.memory.textures
    material.dispose()
    if (renderer.info.memory.textures !== restoredTextures - 1) throw new Error('Restored material retained uploaded lookup')
    return { points: width * height, maxSingleError, maxOctaveError, range: [min, max], lookupBytes: gradient.image.data?.byteLength,
      reusedIdentically: true, cloneSurvivesSourceDisposal: true, restoredIdentically: true }
  } finally {
    renderer.setRenderTarget(null); material.dispose(); input.dispose(); mesh.geometry.dispose(); target.dispose()
    renderer.dispose(); renderer.forceContextLoss()
  }
}

/** Restore only scalar noise in a copy of the actual fragment program. */
function proceduralFragment(source: string): string {
  const match = /float\s+snoise\s*\(vec3\s+v\)\s*\{/.exec(source)
  if (!match) throw new Error('Scalar noise entry missing')
  let end = match.index + match[0].length, level = 1
  for (; end < source.length && level; end++) { if (source[end] === '{') level++; if (source[end] === '}') level-- }
  if (level) throw new Error('Unclosed scalar noise')
  return source.slice(0, match.index) + noiseFunctions + source.slice(end)
}

export function checkAsteroidNoiseImages() {
  const width = 128, height = 128, renderer = new WebGLRenderer({ logarithmicDepthBuffer: true })
  renderer.setSize(width, height)
  const camera = new PerspectiveCamera(60, 1, 0.1, 100), results = []
  try {
    for (const ice of [false, true]) for (const samples of [0, 4, 8]) {
      const material = new InstancedAsteroidMaterial(undefined, undefined, ice)
      ownedLookup(material)
      const actual = material.fragmentShader, reference = proceduralFragment(actual)
      const geometry = new SphereGeometry(0.9, 24, 16)
      geometry.setAttribute('surfaceData', new Float32BufferAttribute(new Float32Array(geometry.attributes.position.count * 4).fill(0.3), 4))
      geometry.setAttribute('instanceOrigin', new InstancedBufferAttribute(new Float32Array(9), 3))
      geometry.setAttribute('instanceFade', new InstancedBufferAttribute(new Float32Array([1, 0.45, -0.65]), 1))
      geometry.setAttribute('instanceDetailEnd', new InstancedBufferAttribute(new Float32Array([7, 7, 7]), 1))
      geometry.setAttribute('instanceDetailMix', new InstancedBufferAttribute(new Float32Array([1, 0.5, 0]), 1))
      const mesh = new InstancedMesh(geometry, material, 3)
      for (let i = 0; i < 3; i++) mesh.setMatrixAt(i, new Matrix4().makeScale(0.9 + i * 0.1, 0.8, 1.1).setPosition((i - 1) * 1.5, 0, -5))
      mesh.frustumCulled = false
      const u = material.uniforms
      u.uShapeAmpMin.value = -0.1; u.uShapeAmpMax.value = 0.2; u.uShapeFreq.value = 2.7
      u.uSpinPeriod.value = 10; u.uImpostorReady.value = 1; u.uSurfaceAmbient.value = 0.3; u.uIceFraction.value = 0.5
      u.lightPosition.value.set(3, 5, 1)
      const maps = [[128, 192, 96, 255], [128, 128, 255, 255], [180, 130, 0, 255]].map(pixel => {
        const map = new DataTexture(new Uint8Array(pixel), 1, 1); map.needsUpdate = true; return map
      })
      ;[u.uRockDiffMap.value, u.uRockNorMap.value, u.uRockArmMap.value] = maps
      const depth = new DepthTexture(width, height, UnsignedIntType)
      const target = new WebGLRenderTarget(width, height, { type: HalfFloatType, depthTexture: depth, samples })
      const copy = new DepthCopyPass({ depthPacking: BasicDepthPacking })
      copy.initialize(renderer, true, HalfFloatType); copy.setSize(width, height); copy.setDepthTexture(depth)
      const render = (lookup: boolean) => {
        material.fragmentShader = lookup ? actual : reference; material.needsUpdate = true
        renderer.setRenderTarget(target); renderer.setClearColor(0, 0); renderer.clear(); renderer.render(mesh, camera)
        if (lookup) activeLookup(renderer)
        const color = new Uint16Array(width * height * 4), depthPixels = new Float32Array(width * height * 4)
        renderer.readRenderTargetPixels(target, 0, 0, width, height, color)
        copy.render(renderer, target, null)
        renderer.readRenderTargetPixels((copy as unknown as { renderTarget: WebGLRenderTarget }).renderTarget, 0, 0, width, height, depthPixels)
        return { color, depth: new Uint32Array(depthPixels.buffer), covered: depthPixels.filter((value, i) => i % 4 === 0 && value < 1).length }
      }
      try {
        for (const pose of [0, 1]) {
          u.uSpinTime.value = pose * 2.7; u.uLodVolumetric.value = pose; u.uDetailMapsEnabled.value = pose
          camera.position.set(pose * 0.15, pose * 0.2, 0); camera.updateMatrixWorld(true)
          const before = render(false), candidate = render(true), after = render(false)
          let differences = 0
          for (const key of ['color', 'depth'] as const) for (let i = 0; i < before[key].length; i++) {
            if (before[key][i] !== candidate[key][i] || before[key][i] !== after[key][i]) differences++
          }
          if (!before.covered || differences || renderer.getContext().getError()) throw new Error(`Asteroid image parity ice=${ice},samples=${samples},pose=${pose}: ${differences} changed components, ${before.covered} covered pixels`)
          results.push({ ice, samples, pose, differences, covered: before.covered })
        }
      } finally {
        renderer.setRenderTarget(null); copy.dispose(); target.dispose(); depth.dispose(); maps.forEach(map => map.dispose())
        mesh.dispose(); geometry.dispose(); material.dispose()
      }
    }
    return results
  } finally { renderer.dispose(); renderer.forceContextLoss() }
}

