import { vi } from 'vitest'

vi.mock('@/core/services/ResourceStorage', () => ({
  resourceStorage: { getTexture: () => null }
}))

import { InstancedAsteroidShader } from '@/core/materials/shaders/InstancedAsteroidShader'

describe('L0 вершинный шейдер: varyings облика', () => {
  it('объявляет и заполняет vObjectPos; пер-инстансные хеши считаются в вершиннике', () => {
    const shader = new InstancedAsteroidShader()
    expect(shader.vertexShader).toContain('varying vec3 vObjectPos')
    expect(shader.vertexShader).toContain('vObjectPos = restPos')
    // Анти-ULP-джиттер: во фрагмент едут ГОТОВЫЕ хеши (tintSeed/domainOffset/
    // triOffset), а не сырой сид — интерполяционный шум varying'а не должен
    // проходить через хеш-усиление (fract(sin·47453) ≈ ×4e6)
    expect(shader.vertexShader).toContain('varying float vTintSeed')
    expect(shader.vertexShader).toContain('varying vec3 vDomainOffset')
    expect(shader.vertexShader).toContain('varying vec2 vTriOffset')
    expect(shader.vertexShader).toContain('vTintSeed = hashSurface11(shapeSeed + 3.17)')
    expect(shader.vertexShader).not.toContain('vInstanceSeed')
    expect(shader.fragmentShader).not.toContain('vInstanceSeed')
    // Хеш от интерполированных значений во фрагментнике запрещён. Общее
    // определение может отсутствовать после удаления неиспользуемого чанка.
    const fragmentHashMentions = (shader.fragmentShader.match(/hashSurface11\s*\(/g) ?? []).length
    const fragmentHashDefinitions = (shader.fragmentShader.match(/float\s+hashSurface11\s*\(/g) ?? []).length
    expect(fragmentHashMentions).toBe(fragmentHashDefinitions)
  })

  it('прокидывает объектную нормаль и матрицу объект→view (для аналитической нормали)', () => {
    const shader = new InstancedAsteroidShader()
    expect(shader.vertexShader).toContain('varying vec3 vObjectNormal')
    expect(shader.vertexShader).toContain('varying mat3 vObjToView')
    expect(shader.vertexShader).toContain('vObjectNormal = restNormal')
    expect(shader.vertexShader).toContain('vObjToView = normalMatrix * asteroidNormalMatrix(mat3(instanceMatrix), spin)')
  })
})

sources.src/core/materials/InstancedAsteroidMate:
import { ShaderMaterialParameters } from 'three/src/materials/ShaderMaterial'
import { Color, DataTexture, Uniform } from 'three'
import { AbstractShaderMaterial } from '@/core/materials/AbstractShaderMaterial'
import { InstancedAsteroidShader } from '@/core/materials/shaders/InstancedAsteroidShader'
import type { Actor } from '@/core/models/Actor'
import { resolveLightTint } from '@/core/helpers/lightSource'
import { createSimplexGradientTexture } from '@/core/materials/shaders/lib/SimplexGradientLookup'

class InstancedAsteroidMaterial extends AbstractShaderMaterial {
  private gradients: DataTexture

  /**
   * `model` — актор кольца (единственный вызывающий с реальным телом —
   * AsteroidRingSystem через InstancePool); резолвер сам поднимается к
   * корню дерева. `undefined` — легаси-конструкторы без модели
   * (InstancedAsteroid/AsteroidCluster, сейчас не используются) — тинт
   * остаётся выключенным, как раньше.
   * `useIceVariety` — ледяная примесь пояса (см. чанк AsteroidIce): текст
   * программы собирается с её кусками, дефайн USE_ICE_VARIETY помечает режим.
   * false (дефолт) — путь колец, текст прежний.
   */
  public constructor(model?: Actor, parameters?: ShaderMaterialParameters, useIceVariety: boolean = false) {
    super(parameters)

    const { uniforms, vertexShader, fragmentShader } = new InstancedAsteroidShader({ iceVariety: useIceVariety })

    this.uniforms = uniforms
    this.vertexShader = vertexShader
    this.fragmentShader = fragmentShader

    this.gradients = createSimplexGradientTexture('Asteroid surface gradients')
    this.uniforms.uAsteroidGradients.value = this.gradients

    this.uniforms.uLightColor = new Uniform(new Color(1, 1, 1))
    const lightTint = model ? resolveLightTint(model) : { active: false, color: new Color(1, 1, 1) }
    ;(this.uniforms.uLightColor.value as Color).copy(lightTint.color)
    // Спред обязателен: дефайны из parameters уже лежат в this.defines после super()
    this.defines = {
      ...this.defines,
      ...(lightTint.active && { USE_LIGHT_TINT: '1' }),
      ...(useIceVariety && { USE_ICE_VARIETY: '1' })
    }
  }

  public updateMaterial(): void {}

  public resetMaterial(): void {}

  public override copy(source: this): this {
    if (source === this) return this
    this.gradients.dispose()
    super.copy(source)
    // ShaderMaterial.copy clones texture uniforms; own the clone's lifetime.
    this.gradients = this.uniforms.uAsteroidGradients.value
    return this
  }

  public override dispose(): void {
    // Retain the CPU source and ownership for Three's dispose/reupload cycle.
    this.gradients.dispose()
    super.dispose()
  }
}

export { InstancedAsteroidMaterial }

