// Temporary diagnosis on the existing production runtime, no source-module imports.
window.__connectAsteroidNoise = async runtimeUrl => {
  const runtime = await import(runtimeUrl)
  const get = name => {
    const container = runtime.getInitializedSimulationRuntime().container
    const tokens = [...container.bindings.keys()].filter(token => typeof token === 'object' && token.name === name)
    if (tokens.length !== 1) throw Error('Ambiguous service ' + name)
    return container.get(tokens[0])
  }
  const stats = values => {
    const sorted = values.slice().sort((a, b) => a - b)
    if (!sorted.length) return { count: 0 }
    const q = p => sorted[Math.ceil(sorted.length * p) - 1]
    return { count: sorted.length, p50: q(.5), p95: q(.95), max: sorted.at(-1), mean: values.reduce((a, b) => a + b, 0) / values.length }
  }
  const preserve = (object, key) => {
    const descriptor = Object.getOwnPropertyDescriptor(object, key)
    return () => {
      if (descriptor) Object.defineProperty(object, key, descriptor); else delete object[key]
      const after = Object.getOwnPropertyDescriptor(object, key)
      if (!!after !== !!descriptor || (descriptor && ['value','get','set','writable','configurable','enumerable'].some(k => descriptor[k] !== after[k]))) throw Error('Restore failed: ' + key)
    }
  }
  const encoded = bytes => {
    let text = ''
    for (let i = 0; i < bytes.length; i += 16384) text += String.fromCharCode(...bytes.subarray(i, i + 16384))
    return btoa(text)
  }
  const hash = async bytes => [...new Uint8Array(await crypto.subtle.digest('SHA-256', bytes))].map(x => x.toString(16).padStart(2, '0')).join('')
  const difference = (a, b) => {
    if (a.length !== b.length) throw Error('Buffer size mismatch')
