    i = mod(i, 289.0);
    vec4 gx = i.x + vec4(0.0, i1.x, i2.x, 1.0);
    vec2 zPerm = asteroidLookupPermute(i.z + vec2(0.0, 1.0));
    vec4 gy = vec4(zPerm.x, i1.z == 0.0 ? zPerm.x : zPerm.y, i2.z == 0.0 ? zPerm.x : zPerm.y, zPerm.y)
