    vec3 p0 = textureLod(uAsteroidGradientLookup, (vec2(gx.x, gy.x) + 0.5) / 289.0, 0.0).xyz;
    vec3 p1 = textureLod(uAsteroidGradientLookup, (vec2(gx.y, gy.y) + 0.5) / 289.0, 0.0).xyz;
    vec3 p2 = textureLod(uAsteroidGradientLookup, (vec2(gx.z, gy.z) + 0.5) / 289.0, 0.0).xyz;
    vec3 p3 = textureLod(uAsteroidGradientLookup, (vec2(gx.w, gy.w) + 0.5) / 289.0, 0.0).xyz;
  `
  function lookup(source, derivative) {
    const pattern = derivative ? /vec4\s+snoiseGrad\s*\(vec3\s+v\)\s*\{/ : /float\s+snoise\s*\(vec3\s+v\)\s*\{/
