      }
      return result
    }
    dispose() { for (const item of this.pending) this.gl.deleteQuery(item.query); this.pending = [] }
  }
  return window.__asteroidNoise = {
    async experiment({ smoke = false } = {}) {
      const scene = get('Scene'), camera = get('Camera'), engine = get('Engine'), renderer = get('Renderer'), pp = get('Postprocessing'), gl = renderer.getContext()
      const main = pp.composer.passes.find(pass => pass.name === 'RenderPass'), volume = pp.composer.passes.find(pass => pass.name === 'DepthVolumePass')
      if (!main || !volume) throw Error('Passes absent')
      const borrowed = get('DepthVolumeRegistry').volumes().map(v => v.material?.uniforms?.uDustClumpGradients?.value).find(value => value?.image?.width === 289 && value.image.height === 289)
      if (!borrowed) throw Error('Existing dust gradient table missing')
      const meshes = [], materials = new Set()
      scene.traverse(object => { if (object.isInstancedMesh && /^AsteroidPool_(Near|L0)_/.test(object.name)) { meshes.push(object); materials.add(object.material) } })
      if (!meshes.some(mesh => mesh.count > 0 && mesh.name.startsWith('AsteroidPool_Near_'))) throw Error('No submitted Near geometry')
      const saved = [...materials].map(material => ({ material, vertex: material.vertexShader, fragment: material.fragmentShader,
        lookupVertex: lookup(material.vertexShader, true), lookupFragment: lookup(material.fragmentShader, false), restoreUniform: preserve(material.uniforms, 'uAsteroidGradientLookup') }))
      const patch = mode => {
        for (const entry of saved) {
          entry.material.vertexShader = mode === 'vertex' || mode === 'both' ? entry.lookupVertex : entry.vertex
          entry.material.fragmentShader = mode === 'fragment' || mode === 'both' ? entry.lookupFragment : entry.fragment
          entry.material.uniforms.uAsteroidGradientLookup = { value: borrowed }
          entry.material.needsUpdate = true
        }
      }
      const resetHistory = () => {
        for (const pass of pp.composer.passes) {
          const history = pass.scaled?.history
          if (history) for (const frame of history.records.values()) history.invalidate(frame)
        }
      }
      const result = { images: [], rows: [], hardware: { requestedSamples: pp.composer.multisampling, renderer: gl.getParameter(gl.getExtension('WEBGL_debug_renderer_info').UNMASKED_RENDERER_WEBGL) },
        uniforms: saved.map(({ material }, i) => ({ i, values: Object.fromEntries(Object.entries(material.uniforms).filter(([, uniform]) => typeof uniform.value === 'number').map(([key, uniform]) => [key, uniform.value])) })),
        meshes: meshes.map(mesh => ({ name: mesh.name, material: saved.findIndex(entry => entry.material === mesh.material), count: mesh.count, vertices: mesh.geometry.attributes.position.count, indices: mesh.geometry.index?.count })),
        gradient: { width: 289, height: 289, type: borrowed.type, format: borrowed.format, bytes: borrowed.image.data.byteLength, sha256: await hash(borrowed.image.data) },
        restoration: false }
      const position = camera.position.clone(), rotation = camera.quaternion.clone()
      engine.stop()
