        for (const angle of (smoke ? [0] : [0, 0.27])) {
          camera.position.copy(position); camera.quaternion.copy(rotation); camera.rotateY(angle); camera.updateMatrixWorld(true)
          const buffers = [], records = [], restoreMain = preserve(main, 'render'), originalMain = main.render
          let capture = false, hdr
          main.render = function (...args) {
            const value = originalMain.apply(this, args)
            if (capture) {
              const target = renderer.getRenderTarget()
              if (!target || target.width !== 1280 || target.height !== 720) throw Error('Unexpected main HDR target')
              hdr = new Uint16Array(target.width * target.height * 4)
              renderer.readRenderTargetPixels(target, 0, 0, target.width, target.height, hdr)
            }
            return value
          }
          try {
            for (const [label, mode] of [['baseline-before','baseline'],['vertex','vertex'],['fragment','fragment'],['both','both'],['baseline-after','baseline']]) {
              patch(mode); resetHistory()
              for (let i = 0; i < 16; i++) { capture = i === 15; pp.render(0) }
              const depthTarget = volume.depthCopy.renderTarget, depth = new Float32Array(1280 * 720 * 4), rgba = new Uint8Array(1280 * 720 * 4)
              renderer.readRenderTargetPixels(depthTarget, 0, 0, 1280, 720, depth)
              gl.readPixels(0, 0, 1280, 720, gl.RGBA, gl.UNSIGNED_BYTE, rgba)
              if (!hdr || gl.getError()) throw Error('Image capture failed')
              const depthBits = new Uint32Array(depth.buffer)
              buffers.push({ hdr, depth: depthBits, rgba })
              records.push({ label, mode, rgba: encoded(rgba), png: renderer.domElement.toDataURL('image/png').split(',')[1],
                hdrSha256: await hash(hdr), depthSha256: await hash(depth), rgbaSha256: await hash(rgba) })
            }
          } finally { restoreMain() }
          result.images.push({ angle, records, comparisons: records.slice(1).map((record, i) => ({ label: record.label,
            hdr: difference(buffers[0].hdr, buffers[i+1].hdr), depth: difference(buffers[0].depth, buffers[i+1].depth), rgba: difference(buffers[0].rgba, buffers[i+1].rgba) })) })
          console.log('ASTEROID_NOISE_IMAGES', angle, JSON.stringify(result.images.at(-1).comparisons))
        }
        camera.position.copy(position); camera.quaternion.copy(rotation); camera.updateMatrixWorld(true)
        for (const scope of (smoke ? ['draws'] : ['draws','pass'])) for (const repetition of (smoke ? [0] : [0,1])) {
          const order = repetition ? ['both','fragment','vertex','baseline'] : ['baseline','vertex','fragment','both']
          for (const mode of order) {
            patch(mode); resetHistory()
            for (let i = 0; i < 16; i++) pp.render(0)
            const timers = new Queries(gl), restoreDraw = preserve(renderer,'renderBufferDirect'), restoreMain = preserve(main,'render'), draw = renderer.renderBufferDirect, render = main.render
            let frame = -1
            const counts = {}, frames = smoke ? 8 : 48, cpu = []
            renderer.renderBufferDirect = function (...args) {
              const object = args[4], name = object?.name
              const key = name?.startsWith('AsteroidPool_Near_') ? 'Near' : name?.startsWith('AsteroidPool_L0_') ? 'L0' : null
              if (frame < 0 || !key || scope !== 'draws') return draw.apply(this,args)
              ;(counts[key] ??= Array(frames).fill(0))[frame]++
              return timers.measure(key, frame, () => draw.apply(this,args))
            }
            main.render = function (...args) { return frame >= 0 && scope === 'pass' ? timers.measure('RenderPass',frame,() => render.apply(this,args)) : render.apply(this,args) }
            try {
              for (let i = 0; i < frames; i++) {
                await new Promise(resolve => requestAnimationFrame(resolve))
                frame = i; const start = performance.now(); pp.render(0); cpu.push(performance.now()-start); frame = -1
              }
              const gpu = await timers.finish(), perFrame = {}
              for (const sample of gpu) (perFrame[sample.key] ??= Array(frames).fill(0))[sample.frame] += sample.ms
              if (gl.getError()) throw Error('Profile WebGL error')
              if (scope === 'draws' && (!perFrame.Near || !perFrame.L0)) throw Error('Missing geometry timings')
              result.rows.push({ scope, repetition, mode, frames, cpu, gpu, perFrame, counts, summary: Object.fromEntries(Object.entries(perFrame).map(([key,values]) => [key,stats(values)])) })
              console.log('ASTEROID_NOISE_STAGE', scope, repetition, mode, JSON.stringify(result.rows.at(-1).summary))
            } finally { frame = -1; restoreDraw(); restoreMain(); timers.dispose() }
          }
        }
      } finally {
        for (const entry of saved) { entry.material.vertexShader = entry.vertex; entry.material.fragmentShader = entry.fragment; entry.restoreUniform(); entry.material.needsUpdate = true }
        camera.position.copy(position); camera.quaternion.copy(rotation); camera.updateMatrixWorld(true)
        if (!camera.position.equals(position) || !camera.quaternion.equals(rotation) || saved.some(entry => entry.material.vertexShader !== entry.vertex || entry.material.fragmentShader !== entry.fragment)) throw Error('Experiment restoration failed')
        result.restoration = true
        engine.start()
      }
      return result
    }
  }
}

