import { preview } from 'vite'
import { chromium } from '@playwright/test'
import { readFileSync, writeFileSync } from 'node:fs'
import { createHash } from 'node:crypto'
import { execFileSync } from 'node:child_process'
import assert from 'node:assert/strict'
const root = 'benchmark-results/heavy-scenes/', name = 'asteroid-noise-2026-10-27', base = 'c00a4de416befd402c3587ccb31e7f2a24e05a1d'
const smoke = process.argv.includes('--smoke'), suffix = smoke ? '-smoke' : ''
const output = root + name + suffix + '.json'
const sha = bytes => createHash('sha256').update(bytes).digest('hex')
const git = (...args) => execFileSync('git', args, { encoding: 'utf8' }).trim()
assert.equal(git('rev-parse','HEAD'),base)
assert.equal(git('diff','HEAD','--name-only','--','src','tests','package.json','package-lock.json','vite.config.ts'),'')
const previous = JSON.parse(readFileSync(root + 'volume-batch-v2-2026-10-27.json','utf8'))
assert.equal(previous.outcome,'completed')
for (const file of previous.buildFiles) assert.equal(sha(readFileSync(previous.frozenBundle + '/' + file.path)),file.sha256)
for (const [file, hash] of Object.entries(previous.sourceHashes).filter(([file]) => file.startsWith('src/') || file.startsWith('tests/'))) assert.equal(sha(readFileSync(file)),hash)
const sourcePaths = [root + name + '.browser.js', root + 'run-' + name + '.mjs', root + 'gpu-draws-2026-10-27.browser.js',
  'src/core/materials/shaders/lib/chunks/Noise.ts','src/core/materials/shaders/lib/chunks/AsteroidShape.ts','src/core/materials/shaders/lib/chunks/AsteroidAppearance.ts',
  'src/core/materials/shaders/lib/InstancedAsteroidShaderTemplate.ts','src/core/materials/InstancedAsteroidMaterial.ts','src/core/renderables/DetailedRingStreamingSystem/dust/DustClumpNoise.ts']
const report = { base, startedAt:new Date().toISOString(), smoke, frozenBundle:previous.frozenBundle, buildFiles:previous.buildFiles,
  connection:previous.connection, buildInputHashes:previous.sourceHashes, sourceHashes:Object.fromEntries(sourcePaths.map(file => [file,sha(readFileSync(file))])),
  scenes:[], errors:[], warnings:[], assetFailures:[], sourceModuleRequests:[], requests:[], cloudResponses:0, outcome:'failed',
  scope:'Temporary shader replacement on immutable production build. Borrow existing dust gradient texture; never ship ownership coupling. Original geometry/quality/LOD and remaining arithmetic unchanged. Frozen engine/clock and phase-reset histories for images and timer windows. Exact image gates determine acceptance; timing alone is insufficient.' }
writeFileSync(output,JSON.stringify(report,null,2),{flag:'wx'})
const save = () => writeFileSync(output,JSON.stringify(report,null,2))
let server,browser
try {
  server = await preview({build:{outDir:previous.frozenBundle},base:'/titan-engine-dev/',preview:{host:'127.0.0.1',port:8096,strictPort:true}})
  browser = await chromium.launch({channel:'chrome',headless:true})
  const page = await browser.newPage({viewport:{width:1280,height:720},deviceScaleFactor:1})
  page.on('pageerror',error => report.errors.push(error.stack || error.message))
  page.on('console',message => {
    if (message.type() === 'error') report.errors.push(message.text())
    if (message.type() === 'warning') report.warnings.push(message.text())
    if (message.text().startsWith('ASTEROID_NOISE_')) console.log(message.text())
  })
  page.on('response',response => {
    if (response.status() >= 400) report.assetFailures.push(`${response.status()} ${response.url()}`)
    if (response.url().startsWith('https://storage.yandexcloud.net/') && response.ok()) report.cloudResponses++
  })
  page.on('requestfailed',request => report.assetFailures.push(`${request.failure()?.errorText} ${request.url()}`))
  page.on('request',request => {
    const url = new URL(request.url()), route = url.pathname.replace(/^\/titan-engine-dev(?=\/)/,'')
    report.requests.push({origin:url.origin,path:url.pathname,type:request.resourceType()})
    if (/^\/(?:src|@vite|@id|tests)\//.test(route)) report.sourceModuleRequests.push(url.origin + url.pathname)
  })
  await page.goto('http://127.0.0.1:8096/titan-engine-dev/')
  await page.getByRole('button',{name:/^Run /}).first().waitFor()
  await page.addScriptTag({path:root+'gpu-draws-2026-10-27.browser.js',type:'module'})
  await page.evaluate(c => window.__productionFrame.connect(c.entryUrl,c.runtimeUrl),previous.connection)
  await page.addScriptTag({path:root+name+'.browser.js',type:'module'})
  await page.evaluate(url => window.__connectAsteroidNoise(url).then(() => true),previous.connection.runtimeUrl)
  for (const [id,actor] of (smoke ? [[13,135]] : [[13,135],[12,127]])) {
    console.log('ASTEROID_NOISE_SCENE',id)
    const snapshot = await page.evaluate(id => window.__productionFrame.selectScenario(id),id)
    assert.doesNotMatch(snapshot.renderer,/SwiftShader|software|llvmpipe/i)
    const view = await page.evaluate(actor => window.__productionFrame.setView(actor),actor)
    await page.evaluate(() => window.__productionFrame.settle(96))
    await page.evaluate(() => window.__productionFrame.measure({mode:'plain',motion:true,frames:120}))
    await page.evaluate(actor => window.__productionFrame.setView(actor),actor)
    await page.evaluate(() => window.__productionFrame.settle(96))
    const result = await page.evaluate(options => window.__asteroidNoise.experiment(options),{smoke})
    for (const image of result.images) {
      let reference
      for (const record of image.records) {
        const stem = `${root}${name}${suffix}-${id}-${image.angle}-${record.label}`
        const rgba = Buffer.from(record.rgba,'base64'), png = Buffer.from(record.png,'base64')
        assert.equal(sha(rgba),record.rgbaSha256)
        if (!reference) reference = rgba
        else {
          let differences = 0, maxCodeDifference = 0
          for (let i = 0; i < rgba.length; i++) if (rgba[i] !== reference[i]) { differences++; maxCodeDifference = Math.max(maxCodeDifference,Math.abs(rgba[i]-reference[i])) }
          assert.deepEqual(image.comparisons.find(row => row.label === record.label).rgba,{elements:rgba.length,differences,maxCodeDifference})
        }
        writeFileSync(stem+'.rgba',rgba,{flag:'wx'}); writeFileSync(stem+'.png',png,{flag:'wx'})
        delete record.rgba; delete record.png
        record.rgbaPath=stem+'.rgba'; record.pngPath=stem+'.png'; record.pngSha256=sha(png)
      }
      const control = image.comparisons.find(row => row.label === 'baseline-after')
      assert.equal(control.hdr.differences,0); assert.equal(control.depth.differences,0); assert.equal(control.rgba.differences,0)
    }
    report.scenes.push({id,snapshot,view,...result}); save()
    for (const key of ['errors','warnings','assetFailures','sourceModuleRequests']) assert.deepEqual(report[key],[],key)
    report.scenes.at(-1).afterMenu = await page.evaluate(() => window.__productionFrame.menu())
    save()
  }
  for (const [file, hash] of Object.entries(report.sourceHashes)) assert.equal(sha(readFileSync(file)),hash)
  for (const file of previous.buildFiles) assert.equal(sha(readFileSync(previous.frozenBundle+'/'+file.path)),file.sha256)
  assert.equal(git('diff','HEAD','--name-only','--','src','tests','package.json','package-lock.json','vite.config.ts'),'')
  assert.ok(report.cloudResponses > 0)
  report.outcome = 'completed'
} catch(error) { report.failure=error.stack||error.message; console.error(error); process.exitCode=1 }
finally { report.finishedAt=new Date().toISOString(); save(); await browser?.close(); if(server) await new Promise(resolve => server.httpServer.close(resolve)) }

