// External diagnostic: imports only the already-built application modules.
// No source-module imports, alternative renderer, production patch or render setting changes.
const stats = values => {
  const sorted = values.slice().sort((a, b) => a - b)
  if (!sorted.length) return { count: 0 }
  const quantile = q => sorted[Math.ceil(sorted.length * q) - 1]
  return { count: sorted.length, p50: quantile(.5), p95: quantile(.95), p99: quantile(.99), max: sorted.at(-1), mean: values.reduce((a, b) => a + b, 0) / values.length }
}
const nextFrame = () => new Promise(resolve => requestAnimationFrame(resolve))
const preserve = (object, key) => {
  const descriptor = Object.getOwnPropertyDescriptor(object, key)
  return () => {
    if (descriptor) Object.defineProperty(object, key, descriptor); else delete object[key]
    const restored = Object.getOwnPropertyDescriptor(object, key)
    if (!!restored !== !!descriptor || (descriptor && ['value', 'get', 'set', 'writable', 'configurable', 'enumerable'].some(field => descriptor[field] !== restored[field]))) throw Error(`Descriptor restoration failed: ${key}`)
  }
}
let store, scenarios, runtimeModule, connection
const runtime = () => {
  const value = runtimeModule.getInitializedSimulationRuntime()
  if (!value) throw Error('Production runtime not initialized')
  return value
}
const get = name => {
  const container = runtime().container
  const keys = [...container.bindings.keys()].filter(key => typeof key === 'object' && key.name === name)
  if (keys.length !== 1) throw Error(`Ambiguous/missing production token: ${name}`)
  return container.get(keys[0])
}
const label = object => {
  const names = []
  for (let item = object; item; item = item.parent) names.push(`${item.name || item.type}${item.model ? ':' + item.model.getAttribute('id') : ''}`)
  return names.reverse().join('/')
}

async function connect(entryUrl, runtimeUrl) {
  const entry = await import(entryUrl)
  const stores = Object.entries(entry).filter(([, value]) => value && typeof value === 'object' && typeof value.setScenario === 'function' && 'appLoadingStatus' in value)
  const lists = Object.entries(entry).filter(([, value]) => Array.isArray(value) && value.some(item => item?.id === 13 && Array.isArray(item.defaultCameraPosition)) && value.some(item => item?.id === 12))
  if (stores.length !== 1 || lists.length !== 1) throw Error('Production entry export identification failed')
  store = stores[0][1]; scenarios = lists[0][1]
  runtimeModule = await import(runtimeUrl)
  if (typeof runtimeModule.getInitializedSimulationRuntime !== 'function') throw Error('Production runtime export missing')
  connection = { entryUrl, runtimeUrl, storeExport: stores[0][0], scenariosExport: lists[0][0] }
  return connection
}
async function selectScenario(id) {
  const selected = scenarios.find(item => item.id === id)
  if (!selected) throw Error(`Scenario missing: ${id}`)
  const start = performance.now()
  await store.setScenario(selected)
  if (store.scenario?.id !== id || store.appLoadingStatus) throw Error('Scenario startup failed')
  return { id, name: selected.name, startupMs: performance.now() - start, ...snapshot() }
}
async function menu() {
  await store.setScenario(null)
  await nextFrame(); await nextFrame()
  return snapshot()
}
function snapshot() {
  const renderer = get('Renderer'), gl = renderer.getContext(), debug = gl.getExtension('WEBGL_debug_renderer_info')
  const scene = get('Scene'), camera = get('Camera'), queue = get('NebulaBakeQueue')
  const streamers = []
  scene.traverse(object => {
    if (object.pool?.commitUpdates && object.cascades?.managers) streamers.push({ label: label(object), visible: object.visible, info: object.getDebugInfo() })
  })
  return { scenario: store.scenario?.id ?? null, renderer: gl.getParameter(debug ? debug.UNMASKED_RENDERER_WEBGL : gl.RENDERER),
    userAgent: navigator.userAgent, viewport: [innerWidth, innerHeight], dpr: devicePixelRatio,
    pendingBakes: queue.pendingCount, bakeBytes: queue.allocatedBytes,
    camera: camera.position.toArray(), orientation: camera.quaternion.toArray(), streamers,
    memory: { ...renderer.info.memory }, programs: renderer.info.programs.length,
    heapBytes: performance.memory?.usedJSHeapSize ?? null,
    volumes: get('DepthVolumeRegistry').volumes().map(volume => ({ label: label(volume), visible: volume.visible, resolutionScale: volume.resolutionScale,
      densityReady: volume.material?.uniforms?.uDensityReady?.value, lod: volume.material?.uniforms?.uLodBlend?.value })) }
}
function setView(actorId) {
  const scene = get('Scene'), camera = get('Camera')
  let target, belt
  scene.traverse(object => { if (!target && object.model?.getAttribute('id') === actorId) target = object })
  if (!target) throw Error('Belt actor missing')
  target.traverse(object => { if (object.name === 'AsteroidBelt' && Number.isFinite(object.innerRadiusTu) && Number.isFinite(object.outerRadiusTu)) belt = object })
  if (!belt) throw Error('Production belt missing')
  const center = target.getWorldPosition(camera.position.clone())
  get('CameraController').stopFollowing()
  camera.position.set((belt.innerRadiusTu + belt.outerRadiusTu) / 2, 0, 0).applyMatrix4(belt.matrixWorld)
  camera.lookAt(center); camera.updateMatrixWorld(true)
  get('CameraCollision').reset()
  return { actorId, center: center.toArray(), camera: camera.position.toArray(), orientation: camera.quaternion.toArray(), name: target.model.getAttribute('name') }
}
async function settle(frames = 64) {
  for (let i = 0; i < frames; i++) await nextFrame()
  if (get('NebulaBakeQueue').pendingCount !== 0) throw Error('Bake work remains after warmup')
}

class Queries {
  constructor(gl) {
    this.gl = gl; this.pending = []; this.active = false
    this.ext = gl.getExtension('EXT_disjoint_timer_query_webgl2')
    if (!this.ext || !(gl.getQuery(this.ext.TIME_ELAPSED_EXT, this.ext.QUERY_COUNTER_BITS_EXT) > 0)) throw Error('Native GPU timer unavailable')
    gl.getParameter(this.ext.GPU_DISJOINT_EXT)
  }
  measure(key, frame, callback) {
    if (this.active) throw Error('Nested GPU query')
    const gl = this.gl, query = gl.createQuery()
    if (!query) throw Error('GPU query allocation failed')
    gl.beginQuery(this.ext.TIME_ELAPSED_EXT, query); this.active = true
    try { return callback() }
    finally { gl.endQuery(this.ext.TIME_ELAPSED_EXT); this.active = false; this.pending.push({ query, key, frame }) }
  }
  async finish() {
    const samples = [], gl = this.gl, start = performance.now()
    // Never poll in a measured frame: getParameter may synchronize with the GPU.
    while (this.pending.length) {
      await new Promise(resolve => setTimeout(resolve, 16))
      if (gl.isContextLost() || gl.getParameter(this.ext.GPU_DISJOINT_EXT)) throw Error('GPU context lost/disjoint; discard run')
      while (this.pending.length && gl.getQueryParameter(this.pending[0].query, gl.QUERY_RESULT_AVAILABLE)) {
        const { query, key, frame } = this.pending.shift()
        const ms = gl.getQueryParameter(query, gl.QUERY_RESULT) / 1e6
        gl.deleteQuery(query)
        if (!Number.isFinite(ms) || ms <= 0) throw Error('Invalid GPU sample')
        samples.push({ key, frame, ms })
      }
      if (performance.now() - start > 60000) throw Error('GPU results timeout')
    }
    return samples
  }
  dispose() { for (const { query } of this.pending) this.gl.deleteQuery(query); this.pending = [] }
}

async function measure({ mode = 'plain', motion = false, frames = 240 }) {
  if (!['plain', 'gpu-frame', 'passes', 'volumes', 'cpu', 'attribution'].includes(mode)) throw Error('Unknown mode')
  const engine = get('Engine'), camera = get('Camera'), renderer = get('Renderer'), gl = renderer.getContext(), pp = get('Postprocessing')
  const origin = camera.position.clone(), orientation = camera.quaternion.clone(), direction = camera.position.clone().set(1, 0, 0).applyQuaternion(orientation)
  const initial = snapshot(), oldFrame = engine.renderFrame, restoreFrame = preserve(engine, 'renderFrame'), undo = [], cpu = {}, cpuCalls = {}, draws = {}
  const intervals = [], wholeCpu = [], starts = [], positions = [], queries = ['gpu-frame', 'passes', 'volumes', 'attribution'].includes(mode) ? new Queries(gl) : null
  const blits = {}, materials = {}, targets = {}, workload = {}, targetRefs = new Map(), restoration = { complete: false }
  let frame = -1, measured = 0, failure = null, active = true
  const wrap = (object, method, name, gpu = false) => {
    const original = object[method]
    const restore = preserve(object, method)
    if (typeof original !== 'function') throw Error(`Missing measured method: ${name}`)
    object[method] = function (...args) {
      if (frame < 0) return original.apply(this, args)
      const key = typeof name === 'function' ? name(args) : name
      const start = performance.now()
      try { return gpu ? queries.measure(key, frame, () => original.apply(this, args)) : original.apply(this, args) }
      finally { (cpu[key] ??= Array(frames).fill(0))[frame] += performance.now() - start; (cpuCalls[key] ??= Array(frames).fill(0))[frame]++ }
    }
    undo.push(restore)
  }
  try {
    if (mode === 'attribution') {
      let currentPass = 'outside', readFramebuffer = gl.getParameter(gl.READ_FRAMEBUFFER_BINDING), drawFramebuffer = gl.getParameter(gl.DRAW_FRAMEBUFFER_BINDING)
      const framebufferIds = new Map(), targetIds = new Map()
      const framebufferId = value => {
        if (value === null) return 'default'
        if (!framebufferIds.has(value)) framebufferIds.set(value, 'fb' + framebufferIds.size)
        return framebufferIds.get(value)
      }
      const targetId = target => {
        if (!target) return 'screen'
        if (!targetIds.has(target)) {
          const id = 'rt' + targetIds.size
          targetIds.set(target, id); targetRefs.set(id, target)
          targets[id] = { name: target.texture.name, width: target.width, height: target.height, samplesRequested: target.samples,
            depthBuffer: target.depthBuffer, stencilBuffer: target.stencilBuffer, resolveDepthBuffer: target.resolveDepthBuffer,
            type: target.texture.type, format: target.texture.format, textures: target.textures.length }
        }
        return targetIds.get(target)
      }
      for (const [i, pass] of pp.composer.passes.entries()) {
        const original = pass.render, restore = preserve(pass, 'render')
        pass.render = function (...args) {
          const previous = currentPass; currentPass = `${i}:${pass.name}`
          try { return original.apply(this, args) } finally { currentPass = previous }
        }
        undo.push(restore)
      }
      const originalBind = gl.bindFramebuffer, restoreBind = preserve(gl, 'bindFramebuffer')
      gl.bindFramebuffer = function (target, framebuffer) {
        const result = originalBind.call(this, target, framebuffer)
        if (target === gl.FRAMEBUFFER || target === gl.READ_FRAMEBUFFER) readFramebuffer = framebuffer
        if (target === gl.FRAMEBUFFER || target === gl.DRAW_FRAMEBUFFER) drawFramebuffer = framebuffer
        return result
      }
      undo.push(restoreBind)
      const originalBlit = gl.blitFramebuffer, restoreBlit = preserve(gl, 'blitFramebuffer')
      gl.blitFramebuffer = function (...args) {
        if (frame < 0) return originalBlit.apply(this, args)
        const target = targetId(renderer.getRenderTarget())
        const mask = args[8], read = framebufferId(readFramebuffer), draw = framebufferId(drawFramebuffer)
        const key = `blit:${currentPass}:${target}:${read}->${draw}:${mask}`
        if (!blits[key]) blits[key] = { pass: currentPass, target, read, draw, rects: args.slice(0, 8), mask, filter: args[9],
          color: !!(mask & gl.COLOR_BUFFER_BIT), depth: !!(mask & gl.DEPTH_BUFFER_BIT), stencil: !!(mask & gl.STENCIL_BUFFER_BIT) }
        return queries.measure(key, frame, () => originalBlit.apply(this, args))
      }
      undo.push(restoreBlit)
      const originalDraw = renderer.renderBufferDirect, restoreDraw = preserve(renderer, 'renderBufferDirect')
      renderer.renderBufferDirect = function (...args) {
        if (frame < 0 || currentPass !== '1:RenderPass') return originalDraw.apply(this, args)
        const [, , geometry, material, object, group] = args
        const key = `draw:${currentPass}:${label(object)}:material${material.id}`
        const target = targetId(renderer.getRenderTarget())
        if (!materials[material.id]) materials[material.id] = { name: material.name, type: material.type, defines: { ...material.defines },
          vertexShader: material.vertexShader, fragmentShader: material.fragmentShader, transparent: material.transparent,
          depthWrite: material.depthWrite, depthTest: material.depthTest, blending: material.blending, side: material.side }
        if (!draws[key]) draws[key] = { pass: currentPass, target, object: label(object), objectName: object.name, material: material.id,
          instanced: !!object.isInstancedMesh, geometry: geometry.type, indices: geometry.index?.count ?? 0, vertices: geometry.attributes.position?.count ?? 0 }
        const sourceCount = geometry.index?.count ?? geometry.attributes.position?.count ?? 0
        const start = Math.max(geometry.drawRange.start, group?.start ?? 0)
        const end = Math.min(sourceCount, geometry.drawRange.start + geometry.drawRange.count, group ? group.start + group.count : Infinity)
        const submitted = workload[key] ??= { instances: Array(frames).fill(0), elements: Array(frames).fill(0), calls: Array(frames).fill(0) }
        const instances = object.isInstancedMesh ? object.count : geometry.isInstancedBufferGeometry ? Math.min(geometry.instanceCount, geometry._maxInstanceCount ?? Infinity) : 1
        if (!Number.isFinite(instances) || instances < 0) throw Error('Invalid submitted instance count')
        submitted.instances[frame] += instances; submitted.elements[frame] += Math.max(0, end - start) * instances; submitted.calls[frame]++
        return queries.measure(key, frame, () => originalDraw.apply(this, args))
      }
      undo.push(restoreDraw)
    }
    if (mode === 'passes') for (const [i, pass] of pp.composer.passes.entries()) wrap(pass, 'render', `${i}:${pass.name}`, true)
    if (mode === 'cpu') {
      for (const [name, methods] of [['SceneManager', ['update', 'updateView', 'updateMarkers']], ['SceneObserver', ['tick']], ['CameraCollision', ['resolve']], ['NebulaBakeQueue', ['pumpFrame']], ['AsteroidImpostorLibrary', ['pumpFrame']], ['Postprocessing', ['render']], ['LabelRenderer', ['render']]]) {
        const service = get(name)
        for (const method of methods) wrap(service, method, `${name}.${method}`)
      }
      const pools = new Set(), managers = new Set(), visibilityPrototypes = new Set()
      get('Scene').traverse(object => {
        if (object.pool?.commitUpdates && object.cascades?.managers) {
          pools.add(object.pool)
          for (const manager of object.cascades.managers) managers.add(manager)
          for (const stream of object.pool.streams) if (stream.visibility) visibilityPrototypes.add(Object.getPrototypeOf(stream.visibility))
        }
      })
      if (!pools.size || !managers.size || !visibilityPrototypes.size) throw Error('Missing CPU instrumentation targets')
      for (const pool of pools) { wrap(pool, 'commitUpdates', 'pool.commit'); wrap(pool, 'updateVisibility', 'pool.visibility') }
      for (const manager of managers) { wrap(manager, 'update', 'sectors.update'); wrap(manager, 'allocateForLOD', 'sectors.allocate') }
      for (const proto of visibilityPrototypes) {
        wrap(proto, 'update', 'visibility.geometry'); wrap(proto, 'updateImpostors', 'visibility.impostors'); wrap(proto, 'copyVisible', 'visibility.copy')
      }
      wrap(gl, 'bufferSubData', 'gl.bufferSubData')
      wrap(gl, 'getParameter', args => 'gl.getParameter:' + args[0].toString(16))
    }
    if (mode === 'volumes') {
      let inPass = false, volumeName = 'pass'
      const pass = pp.composer.passes.find(item => item.name === 'DepthVolumePass')
      const passRender = pass.render, scaledRender = pass.scaled.render, direct = renderer.renderBufferDirect
      const restorePass = preserve(pass, 'render'), restoreScaled = preserve(pass.scaled, 'render'), restoreDirect = preserve(renderer, 'renderBufferDirect')
      pass.render = function (...args) { inPass = true; try { return passRender.apply(this, args) } finally { inPass = false } }
      pass.scaled.render = function (...args) { volumeName = label(args[3]); try { return scaledRender.apply(this, args) } finally { volumeName = 'pass' } }
      renderer.renderBufferDirect = function (...args) {
        if (frame < 0 || !inPass) return direct.apply(this, args)
        const [, , geometry, material, object] = args, uniforms = material.uniforms ?? {}, defines = material.defines ?? {}
        const kind = 'DEPTH_VOLUME_RECONSTRUCT' in defines ? 'matched' : 'DEPTH_VOLUME_FALLBACK' in defines ? 'fallback' :
          'currentColor' in uniforms ? 'temporal' : typeof object.bindSceneDepth === 'function' ? (uniforms.uLowResolutionEnabled?.value > 0 ? 'combined' : 'march') :
          uniforms.map?.value?.name === 'DepthVolume stencil reconstruction' ? 'composite' : material.name || material.type
        const key = volumeName + ':' + kind
        draws[key] = { material: material.type, defines, target: renderer.getRenderTarget()?.texture.name, indices: geometry.index?.count, vertices: geometry.attributes.position?.count }
        return queries.measure(key, frame, () => direct.apply(this, args))
      }
      undo.push(() => { restorePass(); restoreScaled(); restoreDirect() })
    }
    await new Promise((resolve, reject) => {
      const timeout = setTimeout(() => reject(Error('Frame measurement timed out')), 180000)
      engine.renderFrame = function () {
        if (!active) return oldFrame.call(this)
        frame = measured
        const progress = frame / (frames - 1)
        if (motion) {
          camera.position.copy(origin).addScaledVector(direction, progress * 2)
          camera.quaternion.copy(orientation); camera.rotateY(progress * Math.PI * 2); camera.updateMatrixWorld(true)
        }
        const start = performance.now()
        if (starts.length) intervals.push(start - starts.at(-1))
        starts.push(start)
        try {
          if (mode === 'gpu-frame') queries.measure('whole-frame', frame, () => oldFrame.call(this))
          else oldFrame.call(this)
          wholeCpu.push(performance.now() - start)
          if (frame === 0 || frame === frames - 1) positions.push({ frame, position: camera.position.toArray(), quaternion: camera.quaternion.toArray() })
          measured++
        } catch (error) { failure = error }
        finally { frame = -1 }
        if (failure || measured === frames) {
          active = false; renderer.setAnimationLoop(null); clearTimeout(timeout); resolve()
        }
      }
    })
    engine.stop()
    if (failure) throw failure
    if (measured !== frames || wholeCpu.length !== frames || intervals.length !== frames - 1) throw Error('Incomplete frame window')
    const gpu = queries ? await queries.finish() : []
    if (mode === 'attribution') {
      // Inspect hardware samples only after the window and query collection. No sync reads inside measured frames.
      const previousRenderbuffer = gl.getParameter(gl.RENDERBUFFER_BINDING)
      try {
        for (const [id, target] of targetRefs) {
          const buffers = renderer.properties.get(target).__webglColorRenderbuffer ?? []
          targets[id].colorRenderbuffers = buffers.map(buffer => {
            gl.bindRenderbuffer(gl.RENDERBUFFER, buffer)
            return { samples: gl.getRenderbufferParameter(gl.RENDERBUFFER, gl.RENDERBUFFER_SAMPLES),
              width: gl.getRenderbufferParameter(gl.RENDERBUFFER, gl.RENDERBUFFER_WIDTH), height: gl.getRenderbufferParameter(gl.RENDERBUFFER, gl.RENDERBUFFER_HEIGHT),
              internalFormat: gl.getRenderbufferParameter(gl.RENDERBUFFER, gl.RENDERBUFFER_INTERNAL_FORMAT) }
          })
        }
      } finally { gl.bindRenderbuffer(gl.RENDERBUFFER, previousRenderbuffer) }
      if (gl.getParameter(gl.RENDERBUFFER_BINDING) !== previousRenderbuffer) throw Error('Renderbuffer restoration failed')
      if (!Object.keys(draws).length || !Object.keys(blits).length) throw Error('Missing draw/blit attribution')
    }
    if (gl.getError() !== gl.NO_ERROR) throw Error('WebGL error after profile')
    const gpuPerFrame = {}, gpuCalls = {}
    for (const sample of gpu) {
      (gpuPerFrame[sample.key] ??= Array(frames).fill(0))[sample.frame] += sample.ms
      ;(gpuCalls[sample.key] ??= Array(frames).fill(0))[sample.frame]++
    }
    if (mode === 'gpu-frame' && gpu.length !== frames) throw Error('Whole-frame query count mismatch')
    return { mode, motion, frames, initial, final: snapshot(), starts, intervals, wholeCpu, positions, cpu, cpuCalls, gpu, gpuPerFrame, gpuCalls, draws, blits, materials, targets, workload, restoration,
      summary: { intervals: stats(intervals), wholeCpu: stats(wholeCpu), cpu: Object.fromEntries(Object.entries(cpu).map(([key, value]) => [key, stats(value)])),
        gpu: Object.fromEntries(Object.entries(gpuPerFrame).map(([key, value]) => [key, stats(value)])) },
      caveat: mode === 'plain' ? 'Actual unchanged production bundle. Only renderFrame wall-time/entry timestamps and frame-indexed camera trajectory are instrumented; no GPU queries, per-component wrappers or CPU profiler. Headless/native cadence is not a cross-device FPS guarantee.' :
        'Separate diagnostic window on the same production bundle; instrumentation overhead present. GPU polling is deferred until after stopping the engine. CPU wall durations can include GPU/driver stalls; component timings can be nested. Per-volume draw queries exclude surrounding renderer work and resolves. Do not sum medians or compare these intervals as FPS against plain windows.' }
  } finally {
    active = false; engine.stop(); restoreFrame()
    for (const restore of undo.reverse()) restore()
    queries?.dispose(); camera.position.copy(origin); camera.quaternion.copy(orientation); camera.updateMatrixWorld(true)
    if (!camera.position.equals(origin) || !camera.quaternion.equals(orientation)) throw Error('Camera restoration failed')
    restoration.complete = true
    engine.start()
  }
}

window.__productionFrame = { connect, selectScenario, menu, snapshot, setView, settle, measure }

