import { readFileSync, writeFileSync, existsSync } from 'node:fs'
import { createHash } from 'node:crypto'
import { gzipSync, gunzipSync } from 'node:zlib'
import { execFileSync } from 'node:child_process'
import assert from 'node:assert/strict'
const root = 'benchmark-results/heavy-scenes/', name = 'asteroid-noise-2026-10-27'
const base = 'c00a4de416befd402c3587ccb31e7f2a24e05a1d'
const output = 'docs/benchmarks/asteroid-noise-2026-10-27.json'
const reviewPath = root + 'asteroid-noise-review-2026-10-27.json'
const sha = bytes => createHash('sha256').update(bytes).digest('hex')
const read = file => { const b = readFileSync(file); return b[0] === 255 && b[1] === 254 ? b.subarray(2).toString('utf16le') : b.toString('utf8').replace(/^\uFEFF/, '') }
const json = file => JSON.parse(read(file))
const pack = file => { const b = readFileSync(file); return { path: file, bytes: b.length, sha256: sha(b), encoding: 'gzip+base64', gzipBase64: gzipSync(b, { level: 9 }).toString('base64') } }
const unpack = record => { const b = gunzipSync(Buffer.from(record.gzipBase64, 'base64')); assert.equal(b.length, record.bytes); assert.equal(sha(b), record.sha256); return JSON.parse(b.toString('utf8')) }
const stats = values => { const a = [...values].sort((a,b) => a-b); assert.ok(a.length); return { count: a.length, p50: a[Math.ceil(a.length*.5)-1], p95: a[Math.ceil(a.length*.95)-1], max: a.at(-1), mean: values.reduce((a,b) => a+b,0)/a.length } }
const attachments = (value, name, found = []) => {
  if (Array.isArray(value)) value.forEach(x => attachments(x,name,found))
  else if (value && typeof value === 'object') {
    if (value.name === name && value.body) found.push(JSON.parse(Buffer.from(value.body,'base64').toString()))
    Object.values(value).forEach(x => attachments(x,name,found))
  }
  return found
}
function profile(report, smoke) {
  assert.equal(report.outcome,'completed'); assert.equal(report.base,base); assert.equal(report.smoke,smoke)
  assert.ok(report.cloudResponses>0); assert.equal(report.scenes.length,smoke?1:2)
  for (const key of ['errors','warnings','assetFailures','sourceModuleRequests']) assert.deepEqual(report[key],[])
  for (const [path,hash] of Object.entries({...report.buildInputHashes,...report.sourceHashes})) assert.equal(sha(readFileSync(path)),hash,path)
  assert.equal(report.buildFiles.length,32)
  for (const file of report.buildFiles) assert.equal(sha(readFileSync(report.frozenBundle+'/'+file.path)),file.sha256)
  for (const request of report.requests.filter(r=>r.type==='script')) {
    assert.equal(request.origin,'http://127.0.0.1:8096')
    assert.ok(report.buildFiles.some(file=>request.path==='/titan-engine-dev/'+file.path),request.path)
  }
  for (const scene of report.scenes) {
    assert.equal(scene.restoration,true); assert.equal(scene.hardware.requestedSamples,8)
    assert.doesNotMatch(scene.hardware.renderer,/SwiftShader|software|llvmpipe/i)
    assert.equal(scene.images.length,smoke?1:2); assert.equal(scene.rows.length,smoke?4:16)
    assert.equal(scene.afterMenu.scenario,null); assert.deepEqual(scene.afterMenu.memory,{geometries:1,textures:0}); assert.equal(scene.afterMenu.programs,0)
    assert.equal(scene.afterMenu.pendingBakes,0); assert.equal(scene.afterMenu.bakeBytes,0); assert.deepEqual(scene.afterMenu.volumes,[]); assert.deepEqual(scene.afterMenu.streamers,[])
    for (const image of scene.images) {
      assert.equal(image.records.length,5); assert.equal(image.comparisons.length,4)
      const reference=readFileSync(image.records[0].rgbaPath)
      for (const record of image.records) {
        const rgba=readFileSync(record.rgbaPath)
        assert.equal(rgba.length,1280*720*4); assert.ok(rgba.equals(reference))
        assert.equal(sha(rgba),record.rgbaSha256); assert.equal(sha(readFileSync(record.pngPath)),record.pngSha256)
        for (const key of ['hdrSha256','depthSha256']) assert.equal(record[key],image.records[0][key])
      }
      for (const check of image.comparisons) for (const key of ['hdr','depth','rgba']) assert.deepEqual(check[key],{elements:1280*720*4,differences:0,maxCodeDifference:0})
    }
    for (const row of scene.rows) {
      const n=smoke?8:48
      assert.equal(row.frames,n); assert.equal(row.cpu.length,n); assert.ok(row.cpu.every(x=>Number.isFinite(x)&&x>=0))
      const frames={},counts={}
      for (const sample of row.gpu) {
        assert.ok(Number.isInteger(sample.frame)&&sample.frame>=0&&sample.frame<n&&Number.isFinite(sample.ms)&&sample.ms>0)
        ;(frames[sample.key]??=Array(n).fill(0))[sample.frame]+=sample.ms
        ;(counts[sample.key]??=Array(n).fill(0))[sample.frame]++
      }
      assert.deepEqual(row.perFrame,frames)
      assert.deepEqual(row.summary,Object.fromEntries(Object.entries(frames).map(([key,values])=>[key,stats(values)])))
      if (row.scope==='draws') { assert.deepEqual(counts,row.counts); assert.deepEqual(Object.keys(frames).sort(),['L0','Near']) }
      else { assert.equal(row.scope,'pass'); assert.deepEqual(counts,{RenderPass:Array(n).fill(1)}) }
      assert.ok(Object.values(counts).every(values=>values.every(x=>x>0)))
    }
    const expected=(smoke?['draws']:['draws','pass']).flatMap(scope=>(smoke?[0]:[0,1]).flatMap(rep=>(rep?['both','fragment','vertex','baseline']:['baseline','vertex','fragment','both']).map(mode=>[scope,rep,mode])))
    assert.deepEqual(scene.rows.map(r=>[r.scope,r.repetition,r.mode]),expected)
  }
}
function analyze(report) {
  return report.scenes.map(scene=>({id:scene.id,rows:['Near','L0','RenderPass'].map(key=>{
    const variants=Object.fromEntries(['baseline','vertex','fragment','both'].map(mode=>[mode,stats(scene.rows.filter(r=>r.mode===mode&&r.perFrame[key]).flatMap(r=>r.perFrame[key]))]))
    return {key,variants,fragmentReductionMs:variants.baseline.p50-variants.fragment.p50,fragmentReductionPercent:(variants.baseline.p50-variants.fragment.p50)/variants.baseline.p50*100,
      windows:scene.rows.filter(r=>r.perFrame[key]).map(r=>({repetition:r.repetition,mode:r.mode,...r.summary[key]}))}
  })}))
}
function diagnosis(report) {
  const records=attachments(report,'browser-diagnostics').flatMap(d=>d.console.filter(c=>c.text.startsWith('ASTEROID_NOISE_IMAGE_DIAGNOSIS ')))
  assert.equal(records.length,1)
  const rows=JSON.parse(records[0].text.slice('ASTEROID_NOISE_IMAGE_DIAGNOSIS '.length))
  assert.equal(rows.length,12)
  assert.deepEqual(rows.map(r=>[r.ice,r.samples,r.pose]),[false,true].flatMap(ice=>[0,4,8].flatMap(samples=>[0,1].map(pose=>[ice,samples,pose]))))
  for(const row of rows) {
    assert.equal(row.controlDifferences,0); assert.equal(row.depthDifferences,0); assert.ok(row.covered>0)
    const rejected=!row.ice&&row.pose===1
    assert.equal(row.differences,rejected?1:0)
    assert.deepEqual(row.changed,rejected?[{key:'color',index:31509,before:12437,actual:12436}]:[])
  }
  return rows
}
function verify(archive) {
  assert.equal(archive.base,base); assert.equal(archive.disposition,'rejected; application and tests restored to BASE')
  const report=unpack(archive.rawProfile); profile(report,false); profile(unpack(archive.smoke),true)
  assert.deepEqual(archive.analysis,analyze(report))
  for(const record of archive.reports) unpack(record)
  const native=unpack(archive.reports.find(r=>r.path.endsWith('native-image-diagnosis-2026-10-27.json')))
  assert.deepEqual(archive.materialImages,diagnosis(native))
  const attempted=unpack(archive.reports.find(r=>r.path.endsWith('native-focused-2026-10-27.json')))
  const scalar=attachments(attempted,'probe-result').find(r=>r.name==='checkAsteroidNoiseLookup')
  assert.equal(scalar.status,'passed'); assert.deepEqual(archive.scalarProbe,scalar.result)
  assert.ok(scalar.result.maxSingleError>0&&scalar.result.maxSingleError<4e-6)
  assert.ok(scalar.result.maxOctaveError>0&&scalar.result.maxOctaveError<4e-6)
  for(const file of archive.provenance) { const b=readFileSync(file.path); assert.equal(b.length,file.bytes,file.path); assert.equal(sha(b),file.sha256,file.path) }
  for(const candidate of archive.candidates) for(const file of candidate.files) {
    assert.equal(sha(readFileSync(file.target)),file.sha256)
    assert.equal(sha(Buffer.from(candidate.sources[file.path],'utf8')),file.sha256)
  }
  for(const path of ['src/core/materials/shaders/lib/SimplexGradientLookup.ts','tests/asteroidSurface/NoiseLookup.spec.ts','tests/asteroidSurface/noiseLookup.gpu.ts']) assert.equal(existsSync(path),false,path)
  assert.equal(execFileSync('git',['diff',base,'--name-only','--','src','tests','package.json','package-lock.json','vite.config.ts'],{encoding:'utf8'}).trim(),'')
  if(archive.review) assert.deepEqual(archive.review,json(reviewPath))
  assert.match(read(root+'asteroid-noise-lifecycle-green-2026-10-27.log'),/7 passed/)
  console.log(JSON.stringify({verified:true,hashes:archive.provenance.length,buildFiles:32,windows:report.scenes.reduce((n,s)=>n+s.rows.length,0),frames:report.scenes.flatMap(s=>s.rows).reduce((n,r)=>n+r.frames,0),queries:report.scenes.flatMap(s=>s.rows).reduce((n,r)=>n+r.gpu.length,0),realScenePoses:4,syntheticPoses:12,rejectedSyntheticPoses:3,cloud:report.cloudResponses,applicationUnchanged:true}))
}
if(process.argv.includes('--verify')) verify(json(output))
else {
  const report=json(root+name+'.json')
  const candidates=['v1','v2'].map(version=>{
    const manifest=root+`asteroid-noise-candidate-${version}-2026-10-27/manifest.json`,files=json(manifest)
    return {version,manifest,files,sources:Object.fromEntries(files.map(f=>[f.path,read(f.target)]))}
  })
  const reportFiles=['native-red','native-focused','native-image-diagnosis'].map(s=>root+`asteroid-noise-${s}-2026-10-27.json`)
  const logFiles=['smoke','full','unit-red','native-red','focused','native-focused','native-image-diagnosis','lifecycle-green'].map(s=>root+`asteroid-noise-${s}-2026-10-27.log`)
  const sourceFiles=[...Object.keys(report.sourceHashes),root+'archive-asteroid-noise-2026-10-27.mjs','docs/superpowers/plans/2026-10-27-asteroid-noise.md',root+'asteroid-noise-original-dust-2026-10-27.ts']
  const reports=reportFiles.map(pack), native=json(reportFiles[2]), attempted=json(reportFiles[1])
  const images=[report,json(root+name+'-smoke.json')].flatMap(r=>r.scenes.flatMap(s=>s.images.flatMap(i=>i.records.flatMap(rec=>[rec.pngPath,rec.rgbaPath]))))
  const paths=[...new Set([...sourceFiles,...reportFiles,...logFiles,...images,root+name+'.json',root+name+'-smoke.json',...candidates.flatMap(c=>[c.manifest,...c.files.map(f=>f.target)]),...(existsSync(reviewPath)?[reviewPath]:[])])]
  const archive={base,createdAt:new Date().toISOString(),title:'Asteroid simplex gradient lookup: faster diagnostic, rejected by exact material image gate',disposition:'rejected; application and tests restored to BASE',
    rawProfile:pack(root+name+'.json'),smoke:pack(root+name+'-smoke.json'),analysis:analyze(report),materialImages:diagnosis(native),scalarProbe:attachments(attempted,'probe-result').find(r=>r.name==='checkAsteroidNoiseLookup').result,
    reports,candidates,sources:Object.fromEntries(sourceFiles.map(p=>[p,read(p)])),logs:Object.fromEntries(logFiles.map(p=>[p,read(p)])),
    validation:{diagnosticCompleted:true,realSceneImagesExact:true,materialImagesExact:false,materialCandidateRejected:true,applicationAndTestsRestored:true,originalApplicationTestHashes:15,
      candidateLifecycleTestsPassed:7,candidateFullSuiteRun:false,candidateBuildRun:false,swiftShaderRun:false,newProductionOptimization:false,pngViewed:[13,12]},
    scope:[
      'One AMD/ANGLE D3D11 native Chrome155 machine,1280x720,DPR1,requested8MSAA. This experiment does not independently inspect renderbuffer sample allocation; previous same-build volume-batching evidence verified actual8RGBA16F samples.',
      'Immutable current production build:32files verified,matching restored source inputs. Assets fetched from Yandex cloud,576successful responses. No source-module requests or application runtime edits in diagnostic build. Three shader variants are temporary replacements with exact restoration, sharing the existing dust texture only in diagnosis.',
      '32windows x48frames=1536measured frames. Engine stopped,clock/camera held,temporal histories reset. Separate Near/L0 draw scopes and RenderPass scope,2forward/reversed orders. Geometry/tessellation/density/LOD/quality untouched. Poll GPU queries after each window. Timings are elapsed GPU scopes,not pure shader occupancy,presentation FPS or full-frame speedup.',
      'Real-scene image gates:2poses per scene,baseline-before/vertex/fragment/both/baseline-after,16phase-reset renders each. All exact inRGBA8,main RenderPass HDR and copieddepth. Final PNG/RGBA files retained locally with hashes; HDR/depth compared and hashed inbrowser,not saved as raw arrays. Native linked-uniform checks were added in candidate fixtures,not in initial production diagnostic.',
      'Fragment-only selected for attempted implementation. Vertex-only regresses L0; combined improves Near but modest total-pass gains over fragment. Alkaid RenderPass windows show scheduling/thermal variability,so retain separate windows. No moving-camera final comparison or full-frame benefit claim.',
      'Candidate owned a separate1,336,336byte RGBA32F table per material; geometry tiers share a material,2materials observed per real scene. Generated dust GLSL/table bytes were unchanged by extraction. Resource tests7passed. Scalar GPU fixture16384points and reuse/clone/context roundtrips returned passed within existing4e-6float tolerance,but scalar values were not bit-exact.',
      'Native candidate fixture overall failed: scalar test encountered2Three context-cleanup INVALID_OPERATION delete warnings already known in existing dust restoration tests; these were retained and not suppressed. Dust probe passed. Material image fixture found a reproducible single green half-float component12437->12436 atindex31509 for ordinary stone/detailpose1 in requested0/4/8MSAA. All12baseline controls and depth buffers exact.9other fixtures exact. This is a numeric parity failure,not a claim of visible degradation; exact compiler/FMA mechanism was not isolated.',
      'Initial focused unit run:86passed,1legacy source-count assertion failed because unused hash declaration disappeared. Candidate assertion updated to allow absent definition; full87case suite not rerun after rejection. RED4unit/2native missing-resource failures retained. Lifecycle-only7cases GREEN. No failing candidate test remains in repository.',
      'Exact image gate was not relaxed. Both implementation snapshots and failing regression evidence retained; all7tracked edited files restored and3new files removed.15original input hashes match; git diff src/tests/configs is empty. No new app build/full suite/SwiftShader run justified after complete reversion; prior completed c00a4de4 validation remains the product baseline.',
      'Other GPUs/drivers,active lens views,long memory soak and rare long-frame causes remain unverified. Menu counters return1geometry/0textures/0programs on both real scenes. Existing dust lookup is not newly invalidated by the different asteroid material counterexample.'
    ],
    reproduction:[
      'At BASE c00a4de4 restore embedded diagnostic sources into an isolated checkout. Historical runner requires volume-batch-v2-2026-10-27.json and its frozen bundle; previous depth-volume-batching archive embeds that report and manifests. Build bytes stay local,not in this JSON. For a new build deliberately refresh provenance guards and use new output names; never overwrite historical evidence.',
      'Run node benchmark-results/heavy-scenes/run-asteroid-noise-2026-10-27.mjs --smoke then without --smoke using native Chrome,cloud assets and prior production build. Browser comparisons/timers do not modify application files. Recalculate same-frame sums then pooled quantiles; do not sum medians from independent scopes.',
      'To reproduce rejected candidate separately,write candidates[v2].sources to their named paths on BASE (then remove after diagnosis). TITAN_BROWSER_CHANNEL=chrome,TITAN_BROWSER_GPU=native; run Playwright tests/browser/gpu.e2e.ts --grep "asteroid noise images". Exact-image failure is the expected result. Scalar/lifecycle probe is under "asteroid noise lookup"; its context-cleanup warning boundary is preserved in the archived result.',
      'Decode packed records with gunzipSync(Buffer.from(gzipBase64,"base64")); check bytes/sha256. Archives include sources/logs/full raw timing report and Playwright result JSON including inline diagnostic attachments. Trace files and harness screenshots referenced by Playwright JSON are not archived. Local PNG/RGBA/build files are only represented by hashes. Run node benchmark-results/heavy-scenes/archive-asteroid-noise-2026-10-27.mjs --verify for local recalculation and provenance checks.'
    ],review:existsSync(reviewPath)?json(reviewPath):null,provenance:paths.map(path=>{const b=readFileSync(path);return {path,bytes:b.length,sha256:sha(b)}})}
  verify(archive);writeFileSync(output,JSON.stringify(archive,null,2)+'\n');console.log(output)
}

