boundaryVerifier.source:
import {readFileSync} from 'node:fs'
import {createHash} from 'node:crypto'
import assert from 'node:assert/strict'
const root='benchmark-results/heavy-scenes/'
const json=file=>JSON.parse(readFileSync(file,'utf8'))
const sha=bytes=>createHash('sha256').update(bytes).digest('hex')
const snapshotPath=root+'asteroid-noise-reviewed-snapshot-2026-10-27.json'
const snapshot=json(snapshotPath),reviewPath=root+'asteroid-noise-review-2026-10-27.json',review=json(reviewPath)
assert.equal(review.base,snapshot.base);assert.equal(review.head,snapshot.head)
assert.deepEqual(review.inputSnapshot,{path:snapshotPath,sha256:sha(readFileSync(snapshotPath)),data:snapshot})
assert.deepEqual(review.findings.critical,[]);assert.deepEqual(review.findings.important,[])
assert.deepEqual(review.findings.minor.map(x=>x.id),['M1'])
assert.deepEqual(review.resolvedFindings.map(x=>x.id),['M1'])
assert.deepEqual(review.deferredFindings,[])
assert.deepEqual(review.declinedToJudge.map(x=>x.id),review.rulings.map(x=>x.id))
for(const file of snapshot.copies) {
  const bytes=readFileSync(file.path)
  assert.equal(bytes.length,file.bytes);assert.equal(sha(bytes),file.sha256)
}
const originalAudit=readFileSync(snapshot.copies[0].path,'utf8').replaceAll('\r\n','\n').trimEnd()
const oldHeading='## Пункт 17 — процедурный шум Near/L0: ускорение с отклонённым кандидатом, 27 октября'
const newHeading='## Пункт 16 — процедурный шум Near/L0: отклонённый кандидат, 27 октября'
assert.equal(originalAudit.split(oldHeading).length,2)
const beforeAudit=originalAudit.replace(oldHeading,newHeading)
const afterAudit=readFileSync('docs/project-audit-2026-10-21.md','utf8').replaceAll('\r\n','\n').trimEnd()
assert.ok(afterAudit.startsWith(beforeAudit+'\n\nЕдинственное независимое финальное ревью этапа'))
assert.equal(afterAudit.slice(beforeAudit.length).trim().split('\n').length,1,'Only review conclusion may be appended')
const before=json(snapshot.copies[1].path),after=json('docs/benchmarks/asteroid-noise-2026-10-27.json')
assert.deepEqual(after.review,review)
const additions=after.provenance.filter(file=>!before.provenance.some(prior=>prior.path===file.path))
assert.equal(additions.length,1);assert.equal(additions[0].path,reviewPath)
assert.equal(additions[0].sha256,sha(readFileSync(reviewPath)))
after.provenance=after.provenance.filter(file=>file.path!==reviewPath)
for(const key of ['createdAt','review']) {delete before[key];delete after[key]}
assert.deepEqual(after,before,'Only review metadata may change after reviewed commit')
console.log(JSON.stringify({verifiedReviewBoundary:true,unchangedEvidenceAndClaims:true,correctedMinor:'M1 heading only',ruledBoundaries:review.rulings.length,deferred:0}))
